import sys
M = 1000000007
def fib(n):
    a, b = 0, 1
    for bit in bin(n)[2:]:
        c = a * ((2 * b - a) % M) % M
        d = (a * a + b * b) % M
        if bit == '1':
            a, b = d, (c + d) % M
        else:
            a, b = c, d
    return a
print(fib(int(sys.argv[1])))

import sys, io, time, runpy, random
M = 1000000007
def ref(n):
    # matrix power reference
    def mul(A, B):
        return ((A[0]*B[0]+A[1]*B[2]) % M, (A[0]*B[1]+A[1]*B[3]) % M,
                (A[2]*B[0]+A[3]*B[2]) % M, (A[2]*B[1]+A[3]*B[3]) % M)
    R = (1, 0, 0, 1); A = (1, 1, 1, 0)
    while n:
        if n & 1: R = mul(R, A)
        A = mul(A, A); n >>= 1
    return R[1]
random.seed(12345)
ns = [10, 1000, 10**18, 0, 1, 2] + [random.randrange(0, 10**18) for _ in range(1500)]
known = {10: 55, 1000: 517691607, 10**18: 209783453, 0: 0, 1: 1, 2: 1}
old_stdout = sys.stdout
t0 = time.perf_counter()
ok = True
for n in ns:
    sys.argv = ['fibmod.py', str(n)]
    buf = io.StringIO(); sys.stdout = buf
    try:
        runpy.run_path('fibmod.py', run_name='__main__')
    finally:
        sys.stdout = old_stdout
    out = buf.getvalue().strip()
    exp = known.get(n)
    if exp is None: exp = ref(n)
    if out != str(exp):
        ok = False; break
t1 = time.perf_counter()
print(1000.0 / (t1 - t0) if ok else 0)
